<?php
namespace Reseller\Tests\Http;

// CLI-only test: must never run through the web server.
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }

use Reseller\Tests\Support\FixtureBuilder;
use Reseller\Tests\Support\RunnerProcess;
use Reseller\Tests\Support\TestDatabase;
use Reseller\Tests\Support\Wp2HttpTestCase;

/**
 * Lab finding B-L04 (ITC NetCore lab 2026-10-24, real FreeRADIUS + CHR): the FreeRADIUS account generated by grants.php
 * had no privilege on `nasreload`, so the stock FreeRADIUS 3.2.x simultaneous-use query (identical in the pinned 3.2.8
 * image and Ubuntu 3.2.5) failed with ERROR 1142 on every PPPoE request and the stock Simultaneous-Use layer was silently
 * off (the product admission guard still enforced single sessions). The harness never saw it because its FreeRADIUS
 * connects as root. FreeRADIUS's own setup.sql grants SELECT, INSERT, UPDATE on nasreload to its account.
 * The generated account must run the stock session queries, and still reach no billing table.
 */
final class W10GrantsFreeRadiusAccountTest extends Wp2HttpTestCase
{
    private static string $radUser = '';
    private static string $radPass = '';

    public static function setUpBeforeClass(): void
    {
        parent::setUpBeforeClass();
        $fx = new FixtureBuilder(dirname(__DIR__, 2));
        $fx->loadSqlFile(static::$db->pdo, dirname(__DIR__, 2) . '/install/freeradius/nuxr_admission.sql');
        $fx->loadSqlFile(static::$db->pdo, dirname(__DIR__, 2) . '/install/freeradius/nuxr_hs_admission.sql');
        // the installer puts the RADIUS tables in the application database (install/step4.php, "radius = yes"), which is
        // where grants.php looks; the HTTP fixture keeps them elsewhere, so the shipped definitions of the two tables the
        // stock session queries use (install/radius.sql) are created here
        $sql = (string) file_get_contents(dirname(__DIR__, 2) . '/install/radius.sql');
        foreach (['radacct', 'nasreload'] as $t) {
            $start = strpos($sql, 'CREATE TABLE `' . $t . '`');
            static::$db->exec(str_replace('CREATE TABLE `' . $t . '`', 'CREATE TABLE IF NOT EXISTS `' . $t . '`', substr($sql, $start, strpos($sql, ';', $start) - $start)));
        }
        self::$radUser = 'w10rad' . bin2hex(random_bytes(3));
        self::$radPass = bin2hex(random_bytes(16));
    }

    public static function tearDownAfterClass(): void
    {
        try {
            FixtureBuilder::connect(static::$db->host, TestDatabase::rootPassword())->exec("DROP USER IF EXISTS '" . self::$radUser . "'@'%'");
        } finally {
            parent::tearDownAfterClass();
        }
    }

    public function testTheGeneratedFreeRadiusAccountRunsTheStockSessionQueriesAndNothingElse(): void
    {
        $this->assertSame(1, (int) static::$db->value("SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'nasreload'"), 'fixture: nasreload exists');
        $g = RunnerProcess::exec([PHP_BINARY, static::$app->dir . '/system/reseller/grants.php', "--app='w10app'@'%'", "--radius='" . self::$radUser . "'@'%'"]);
        $this->assertSame(0, $g['exit'], $g['raw']);
        $admin = FixtureBuilder::connect(static::$db->host, TestDatabase::rootPassword());
        $admin->exec("CREATE USER '" . self::$radUser . "'@'%' IDENTIFIED BY " . $admin->quote(self::$radPass));
        $mine = array_filter(explode("\n", $g['raw']), fn(string $l): bool => str_starts_with($l, 'GRANT ') && str_ends_with(rtrim($l, ';'), "TO '" . self::$radUser . "'@'%'"));
        $this->assertNotEmpty($mine, 'grants were generated for the FreeRADIUS account');
        $this->assertNotEmpty(array_filter($mine, fn(string $l): bool => str_contains($l, '`radacct`')), "radacct granted:\n" . implode("\n", $mine));
        foreach ($mine as $stmt) {
            $admin->exec(rtrim($stmt, ';'));
        }
        $rad = new \PDO('mysql:host=' . static::$db->host . ';dbname=' . static::$db->name . ';charset=utf8mb4', self::$radUser, self::$radPass, [\PDO::ATTR_ERRMODE => \PDO::ERRMODE_EXCEPTION]);
        // the stock FreeRADIUS 3.2.x simul_count_query (mods-config/sql/main/mysql/queries.conf) and its Accounting-On upsert
        $count = $rad->query("SELECT COUNT(*) FROM radacct a LEFT OUTER JOIN nasreload n USING (nasipaddress) WHERE username = 'w10-nobody'"
            . " AND acctstoptime IS NULL AND (a.acctstarttime > n.reloadtime OR n.reloadtime IS NULL)")->fetchColumn();
        $this->assertSame(0, (int) $count, 'stock simultaneous-use query runs as the FreeRADIUS account');
        $rad->exec("INSERT INTO nasreload (nasipaddress, reloadtime) VALUES ('192.0.2.77', NOW()) ON DUPLICATE KEY UPDATE reloadtime = NOW()");
        $this->assertSame(1, (int) $rad->query("SELECT COUNT(*) FROM nasreload WHERE nasipaddress = '192.0.2.77'")->fetchColumn(), 'Accounting-On reload mark recorded');
        // unchanged boundary: no billing table, no DELETE anywhere
        foreach (['SELECT COUNT(*) FROM tbl_customers', 'SELECT COUNT(*) FROM tbl_manager_ledger', "DELETE FROM nasreload WHERE nasipaddress = '192.0.2.77'", 'DELETE FROM radacct WHERE radacctid = 0'] as $sql) {
            try {
                $rad->query($sql);
                $this->fail('the FreeRADIUS account was allowed: ' . $sql);
            } catch (\PDOException $e) {
                $this->assertContains((int) ($e->errorInfo[1] ?? 0), [1142, 1143], $sql . ': ' . $e->getMessage());
            }
        }
        $admin->exec("DELETE FROM `" . static::$db->name . "`.nasreload WHERE nasipaddress = '192.0.2.77'");
    }
}
